 17	const VERDICT_FORMAT = 'VERDICT: <TRUE|FALSE|MISLEADING|UNVERIFIABLE>'
 18	
 19	export function transcriptHasContent(transcript: string): boolean {
 20	  return /\S/.test(transcript)
 21	}
