 23	export function buildFactCheckClaimPrompt(claim: string): string {
 24	  const clean = claim.trim()
 25	  return (
 26	    `Fact-check the following claim. Respond in EXACTLY this format and nothing else:\n${VERDICT_FORMAT}\n` +
 27	    'then 2-4 short bullet points (each ≤15 words) explaining why; if it is false or misleading, include the correct fact. Be fast and precise.\n\n' +
 28	    `Claim: "${clean}"`
 29	  )
 30	}
