 32	export const FACT_CHECK_SCREEN_PROMPT =
 33	  `Fact-check the most prominent claim visible on my screen. Respond in EXACTLY this format and nothing else:\n${VERDICT_FORMAT}\n` +
 34	  'then 2-4 short bullet points (each ≤15 words); if a claim is false or misleading, include the correct fact. Be fast and precise.'
 35	
 36	export function buildWhatNextPrompt(transcript: string, source: 'transcript' | 'screen'): string {
 37	  if (source === 'screen') {
 38	    return (
 39	      'Based on what is visible on my screen, give me the next useful thing to say or do. ' +
 40	      'If there is not enough context, say what context is missing in one short line, then give the safest useful next move.'
 41	    )
 42	  }
 43	  const tx = transcript.trim()
 44	  return (
 45	    'Based on this live conversation, what should I say NEXT to move it forward? Give me the exact words to say, concise and first person.\n\n' +
 46	    'Transcript (THEM = the other person, YOU = me):\n"""\n' +
 47	    tx.slice(-3000) +
 48	    '\n"""'
 49	  )
 50	}
 51	
 52	export function buildExplainPrompt(input: string, transcript: string): { prompt: string; source: 'input' | 'transcript' | 'generic' } {
 53	  const clean = input.trim()
 54	  if (clean) {
 55	    return { source: 'input', prompt: `Explain this in simple terms:\n"""\n${clean}\n"""` }
 56	  }
 57	  const tx = transcript.trim()
 58	  if (tx) {
 59	    return { source: 'transcript', prompt: `Explain the key point in this conversation in simple terms:\n"""\n${tx.slice(-3000)}\n"""` }
 60	  }
 61	  return {
 62	    source: 'generic',
 63	    prompt: 'Explain what I should focus on right now. If you need more context, say exactly what to provide.'
 64	  }
 65	}
