 67	export function buildSpotlightRefPrompt(transcript: string, typed: string): string {
 68	  const tx = transcript.trim()
 69	  const input = typed.trim()
 70	  const context = input || tx.slice(-3000)
 71	  return (
 72	    'Based on the use case being discussed below, search our references and tell me what relevant sales ' +
 73	    'references or case studies we have, and call out the gaps. Be specific.\n\n' +
 74	    'Use case:\n"""\n' +
 75	    context +
 76	    '\n"""'
 77	  )
 78	}
