 84	export function quickActionUnavailableMessage(kind: QuickActionKind): string {
 85	  if (kind === 'summarize') {
 86	    return 'To summarize, start Listen for a transcript or switch to a screen-capable provider in Settings.'
 87	  }
 88	  if (kind === 'factcheck') {
 89	    return 'Type a claim, start Listen, or switch to a screen-capable provider before fact-checking.'
 90	  }
 91	  if (kind === 'whatnext') {
 92	    return 'Start Listen, type context, or switch to a screen-capable provider so Métis has context for the next move.'
 93	  }
 94	  return 'Type context, start Listen, or switch to a screen-capable provider before using this action.'
 95	}
