 97	export function chooseQuickActionRoute(input: QuickActionRouteInput): QuickActionRoute {
 98	  const hasTranscript = transcriptHasContent(input.transcript)
 99	  const hasInput = /\S/.test(input.input)
100	
101	  if (input.kind === 'whatnext') {
102	    if (hasTranscript) return { target: 'copilot', transport: 'suggest' }
103	    if (input.canUseScreen) return { target: 'answer', transport: 'screen' }
104	    return { target: 'answer', transport: hasInput ? 'text' : 'local-error' }
105	  }
106	
107	  if (input.kind === 'factcheck') {
108	    if (hasInput || hasTranscript) return { target: 'answer', transport: 'text' }
109	    if (input.canUseScreen) return { target: 'answer', transport: 'screen' }
110	    return { target: 'answer', transport: 'local-error' }
111	  }
112	
113	  if (input.kind === 'explain') {
114	    // The user typed something explicit to explain — that wins regardless of screen availability.
115	    if (hasInput) return { target: hasTranscript ? 'copilot' : 'answer', transport: 'text' }
116	    // No typed input: "Explain" with nothing specified defaults to the screen (its classic overlay
117	    // meaning — "explain what I'm looking at") rather than the merely-present meeting transcript.
118	    if (input.canUseScreen) return { target: 'answer', transport: 'screen' }
119	    if (hasTranscript) return { target: 'copilot', transport: 'text' }
120	    return { target: 'answer', transport: 'text' }
121	  }
122	
123	  if (input.kind === 'summarize') {
124	    // "Summarize SCREEN" must actually look at the screen whenever it can — a transcript merely being
125	    // present (i.e. any time a meeting is running) must not silently swap this for a transcript summary.
126	    if (input.canUseScreen) return { target: 'answer', transport: 'screen' }
127	    if (hasTranscript) return { target: 'answer', transport: 'text' }
128	    return { target: 'answer', transport: 'local-error' }
129	  }
130	
131	  return { target: 'answer', transport: 'local-error' }
132	}

